import { useEffect, useState } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";

import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchPRData,      // keep if you still use /prs
  fetchPRStatus     // ✅ make sure this is exported from githubApi.js
} from "./api/githubApi";

import MonthYearPicker from "./components/MonthYearPicker";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

function App() {
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");
  const [mode, setMode] = useState("daily");

  const [labels, setLabels] = useState([]);
  const [counts, setCounts] = useState([]);
  const [total, setTotal] = useState(0);

  // month/year
  const [userCreatedAt, setUserCreatedAt] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  // status counts
  const [openPRs, setOpenPRs] = useState(0);
  const [closedPRs, setClosedPRs] = useState(0);
  const [mergedPRs, setMergedPRs] = useState(0);

  // save token from URL once
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const token = query.get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // auto load user + repos
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    fetchLoggedUser().then(res => {
      // backend should now return full user JSON from GitHub
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then(res => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // TODAY button -> use status analytics for today
  const fetchToday = async () => {
    const today = new Date().toISOString().slice(0, 10);

    const payload = {
      owner,
      repo: selectedRepo,
      startDate: today,
      endDate: today,
      mode: "daily"
    };

    const res = await fetchPRStatus(payload);

    setLabels(res.data.labels);
    setCounts(res.data.counts);
    setTotal(res.data.total);
    setOpenPRs(res.data.open);
    setClosedPRs(res.data.closed);
    setMergedPRs(res.data.merged);
  };

  // NORMAL FETCH (uses selected month + year)
  const fetchData = async () => {
    if (!startDate || !endDate) {
      alert("Please select month and year first");
      return;
    }

    const payload = {
      owner,
      repo: selectedRepo,
      startDate,
      endDate,
      mode
    };

    const res = await fetchPRStatus(payload);

    setLabels(res.data.labels);
    setCounts(res.data.counts);
    setTotal(res.data.total);
    setOpenPRs(res.data.open);
    setClosedPRs(res.data.closed);
    setMergedPRs(res.data.merged);
  };

  const data = {
    labels,
    datasets: [
      {
        label: "Pull Requests",
        data: counts,
        backgroundColor: "#4F46E5"
      }
    ]
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>GitHub Analytics Dashboard</h1>

      {!owner && (
        <button
          onClick={() =>
            (window.location.href = "http://localhost:8080/auth/github")
          }
          style={styles.loginBtn}
        >
          Login with GitHub
        </button>
      )}

      {owner && <h3>Logged in as: {owner}</h3>}

      {owner && (
        <div style={styles.form}>
          {/* Repo Dropdown */}
          <select
            value={selectedRepo}
            onChange={e => setSelectedRepo(e.target.value)}
          >
            {repos.map(repo => (
              <option key={repo.id} value={repo.name}>
                {repo.name}
              </option>
            ))}
          </select>

          {/* Month + Year Picker */}
          <MonthYearPicker
            userCreatedAt={userCreatedAt}
            onChange={({ startDate, endDate }) => {
              setStartDate(startDate);
              setEndDate(endDate);
            }}
          />

          {/* Mode */}
          {/* <select value={mode} onChange={e => setMode(e.target.value)}>
            <option value="daily">Daily</option>
            <option value="monthly">Monthly</option>
            <option value="yearly">Yearly</option>
          </select> */}

          <button onClick={fetchData}>Analyze</button>
          <button onClick={fetchToday}>Today</button>
        </div>
      )}

      {total > 0 && (
        <>
          {/* Status cards */}
          <div style={styles.cardGrid}>
            <div style={styles.statCard}>Total PRs: {total}</div>
            <div style={styles.statCardGreen}>Open PRs: {openPRs}</div>
            <div style={styles.statCardYellow}>Closed PRs: {closedPRs}</div>
            <div style={styles.statCardBlue}>Merged PRs: {mergedPRs}</div>
          </div>

          {/* Chart */}
          <div style={{ width: "90%", maxWidth: 950 }}>
            <Bar data={data} />
          </div>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    textAlign: "center",
    padding: 30,
    fontFamily: "Arial",
    background: "#F8FAFC",
    minHeight: "100vh"
  },
  heading: {
    color: "#1E293B"
  },
  form: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginBottom: 30,
    flexWrap: "wrap"
  },
  loginBtn: {
    padding: "10px 20px",
    borderRadius: 6,
    border: "none",
    background: "#111827",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
    marginBottom: 20
  },
  cardGrid: {
    display: "flex",
    gap: 15,
    justifyContent: "center",
    marginBottom: 25,
    flexWrap: "wrap"
  },
  statCard: {
    padding: 15,
    borderRadius: 8,
    background: "#E5E7EB",
    minWidth: 120,
    fontWeight: "bold"
  },
  statCardGreen: {
    padding: 15,
    borderRadius: 8,
    background: "#DCFCE7",
    color: "#166534",
    minWidth: 120,
    fontWeight: "bold"
  },
  statCardYellow: {
    padding: 15,
    borderRadius: 8,
    background: "#FEF9C3",
    color: "#854D0E",
    minWidth: 120,
    fontWeight: "bold"
  },
  statCardBlue: {
    padding: 15,
    borderRadius: 8,
    background: "#DBEAFE",
    color: "#1E40AF",
    minWidth: 120,
    fontWeight: "bold"
  }
};

export default App;
